begin
 for d in select value from jsonb_array_elements(document->'programmes') loop
  source:=d->>'url';
  insert into public.via_opportunities(id,kind,slug,title,overview,location,province,website_url,application_url,source_url,source_name,last_verified_at,academic_year,published)
  select (d->>'id')::uuid,'programmes',d->>'slug',d->>'title',coalesce(d->>'detail','Explore this programme and its published requirements. Meeting minimums does not guarantee admission.'),i.location,i.province,source,i.application_url,source,'Official institution programme information','2026-10-18T00:00:00Z',2027,true from public.via_opportunities i where i.id=(d->>'institution_id')::uuid;
  insert into public.via_programmes(id,institution_id,field,qualification,duration,minimum_aps,mathematics_required) values((d->>'id')::uuid,(d->>'institution_id')::uuid,d->>'field',d->>'qualification',d->>'duration',(d->>'aps')::numeric,case when d->>'n'='13' then true else null end);
  insert into public.via_admission_rules(programme_id,academic_year,scoring_system,minimum_aps,subject_rules,requirements_complete,requires_bachelor_pass,notes,source_url,source_name,last_verified_at,qualification_gate,aps_alternatives,score_source_url)
  values((d->>'id')::uuid,2027,case when d->>'gate'='unknown' then 'unsupported' else coalesce(d->>'score','uj_nsc_six_v1') end,(d->>'aps')::numeric,d->'rules',d->>'gate'<>'unknown',d->>'gate'='bachelor',coalesce(d->>'detail','NSC academic minimums only; selection, places and final certification remain with the institution.'),source,'Official institution programme information','2026-10-18T00:00:00Z',d->>'gate',coalesce(d->'aps_alternatives','[]'),coalesce(d->>'score_url','https://www.uj.ac.za/wp-content/uploads/2026/07/uj_undergrad_prospectus2027_online_25jun2026.pdf'));
  for r in select value from jsonb_array_elements(d->'rules') loop
   insert into public.via_programme_requirements(programme_id,subject,minimum_percentage,detail,source_url,source_name,last_verified_at,academic_year)
   values((d->>'id')::uuid,r->>'label',(r->>'minimum_percentage')::numeric,case when r ? 'alternatives' then (select string_agg(s.label||' at least '||(a->>'minimum_percentage')||'%', ' OR ') from jsonb_array_elements(r->'alternatives') a join public.via_onboarding_options s on s.id=a->>'subject_id') else 'At least '||(r->>'minimum_percentage')||'% in the listed subject.' end,source,'Official programme requirements','2026-10-18T00:00:00Z',2027);
  end loop;
  if jsonb_array_length(d->'rules')=0 then
   insert into public.via_programme_requirements(programme_id,subject,detail,source_url,source_name,last_verified_at,academic_year) values((d->>'id')::uuid,'Confirm current intake requirements',d->>'detail',source,'Official institution prospectus','2026-10-18T00:00:00Z',2027);
  end if;
 end loop;
 for d in select value from jsonb_array_elements(document->'accommodation') loop
  insert into public.via_opportunities(id,kind,slug,title,overview,location,province,website_url,application_url,source_url,source_name,last_verified_at,published) values((d->>'id')::uuid,'accommodation','connected-housing-'||(d->>'n'),d->>'title','Official residence information and application guidance. Confirm your campus, room options, price and availability directly with the provider.',d->>'location',d->>'province',d->>'url',d->>'apply',d->>'url','Official student housing information','2026-10-18T00:00:00Z',true);
  insert into public.via_accommodations(id,accommodation_type) values((d->>'id')::uuid,'Student residence information');
  insert into public.via_accommodation_institutions(accommodation_id,institution_id,source_url,source_name,last_verified_at) values((d->>'id')::uuid,(d->>'institution_id')::uuid,d->>'url','Official housing association','2026-10-18T00:00:00Z');
 end loop;
end $seed$;
